  "m1.found": "Mallattoowwan argaman",
  "m1.heur": "Seeronni hewuristiksii boca URL toora malee sakatta'u. Yeroo eyyamametti, beekumsi balaa toora interneetii haala iccitii eeguun gaafatama.",
  "m1.heur_offline": "Sakatta'a hewuristiksii toora malee qofa. Sakatta'iinsa kanaaf beekumsi balaa toora interneetii hin gaafatamne.",
  "m1.heur_online": "Sakatta'iinsa caasaa hewuristiksii naannoo fi beekumsa balaa toora interneetii iccitii eegu walitti madaala.",
  "m1.ind.IND-01": "Teessoon lakkoofsa IP qofa. Tajaajiloonni seera qaban idaan IP irratti seenuuf yeroo baay’ee hin gaafatan.",
  "m1.ind.IND-02": "Barreeffamni @ dura jiru Browser dhaan tuffatama; maqaa dhugaa dhoksuu danda’a.",
  "m1.ind.IND-03": "Punycode (xn--) arfii wal fakkaatan domeenii biraa fakkeessuuf dhoksuu danda’a.",
  "m1.ind.IND-04": "Kutaaleen maqaa shan ykn isaa ol; subdomeeniin dheeraan domeenii dhugaa dhoksuu danda’a.",
  "m1.ind.IND-05": "Linkiin http fayyadama, https miti; kanaaf daataan hin dhoksamne. Kun qofa marsariitii miidhaa hin taasisu.",
  "m1.ind.IND-06": "Gabaabsaan linkii bakka dhumaa dhoksa.",
  "m1.ind.IND-07": "Jechoonni (login, verify, account fakkaatan) phishing keessatti baay’inaan argamu; marsariitiiwwan seera qabanii irrattis ni argamu.",
  "m1.ind.IND-08": "Linkiin baay’ee dheeraan kutaa barbaachisaa dhoksuu danda’a.",
  "m1.ind.IND-09": "Koodii percent baay’ee ta’uun bakka dhugaa dhoksuu danda’a.",
  "m1.ind.IND-10": "Poortiin idilee hin taane marsariitii ummataa idilee irratti hin baramne.",
  "m1.ind.TXT-01": "Gaaffii jecha icciitii, koodii mirkaneessaa ykn OTP",
  "m1.ind.TXT-02": "Akeekkachiisa ariifachiisaa fi cufamuu herregaa",
  "m1.ind.TXT-03": "Maqaa dhaabbata beekamaa (Baankii, Teelee, Mootummaa) fayyadamuu",
  "m1.ind.TXT-04": "Kajeellaa qarshii, badhaasa lotarii ykn ispoonsara sobaa",
  "m1.ind.TXT-05": "Gaaffii kaffaltii dursaa, qulqulleessaa ykn tajaajilaa",
  "m1.ind.TXT-06": "Geessituu shakkisiisaa, gabaabfamaa ykn lakkoofsa IP of keessaa qaba",
  "m1.ind.TXT-07": "Gara Telegram/WhatsApp fi appii APK hin mirkannoofnetti qajeelchuu",
  "m1.ind.TXT-08": "Imeelii dhuunfaa/bilisaa dhaabbata fakkeessu",
  "m1.ind.TXT-09": "Gaaffii Maqaa Baankii, Lakkoofsa Herregaa, ykn Ragaa Faayinaansii",
  "m1.ind.TXT-10": "Gaaffii Ragaa Eenyummaa Dhuunfaa fi Odeeffannoo Hawaasummaa",
  "m1.indicators_detected": "Mallattoolee",
  "m1.input_help": "Barreeffama geessituu guutuu asitti maxxansaa. Geessituun Browser kee keessatti akka barreeffamaatti qofa qoratama; serveriin gonkumaa hin qunnamamu, hin fe'amu, ykn hin banamu. Sakatta'iinsi toora-alaa battalatti hojjeta; toora interneetii immoo filannoof dhihaate.",
  "m1.input_help_email": "Imeelii as galchaa. Himoota ergaa, ariifachiisummaa, kaffaltii fi linkiiwwan Browser keessan keessatti qofa qoratamu.",
  "m1.input_help_message": "Barreeffama ergaa as galchaa. Seerota hewuristiksii naannoo fayyadamuun Browser keessan keessatti qofa qoratama; gara serverii kamittuu hin ergamu.",
  "m1.label": "Geessituu qoramu (barreeffama qofa)",
  "m1.label_email": "Barreeffama imeelii qoramu (Ergaa, Maqaa Ergaa, Qabiyyee)",
  "m1.label_message": "Barreeffama ergaa qoramu (SMS, WhatsApp, Telegram, Miidiyaa Hawaasaa)",
  "m1.limits": "Daangaa: qabiyyee fuulaa, umurii domeenii, ragaa fi ce’umsa hin ilaalu; domeenii wal fakkaatu dogoggorsuu danda’a; linkii miidhaa hin qabne shakkuu danda’a.",
  "m1.limits_email": "Daangaa: Qaaccessi barreeffama toora-irraa-alaa jechoota ergaa, maqaa ergituu fi hidhatawwan qorata. Sarvaroota imailli (SPF, DKIM, DMARC) qorachuu yookiin faayiloota ergaa waliin dhufan qorachuu hin danda'u. Ergaan akeekkachiisa hin qabne akka dhugaa ta'etti hin mirkanaa'u.",
  "m1.limits_txt": "Daangaa: Hewuristiksiin boca barreeffamaa qofa qorata; eenyummaa dhugaa nama erge sanaa mirkaneessuu hin danda'u.",
  "m1.local": "Geessituun Browser kee keessatti akka barreeffamaatti qofa xiinxalama. Gonkumaa hin banamu, hin fidamu, yookiin hin banamu.",
  "m1.lvl.caution": "Of Eeggannoo",
  "m1.lvl.high": "Balaa Ol'aanaa",
