  "m1.scope_ml_lexical": "Kilaasifaayara ML toora-ala (mallattoolee 12)",
  "m1.scope_no_content_leak": "Qorannoo naannoo qofa: barreeffamni kun gara serverii kamittuu hin ergamu",
  "m1.scope_no_fetch": "URL gonkumaa hin banamne: URL serverii irraa hin fe'amne yookiin hin banamne",
  "m1.scope_title": "Daangaa Mirkaneessaa",
