  "academy.stage1.title": "Sadarkaa 1: Hubannoo Bu'uuraa hanga Ittisa Tarsiimawaa (Sadarkaa 1–6)",
  "academy.stage1.desc": "Saayibarii bu'uuraa, beekamtii sodaawwanii, dhuunfaa, deebii balaa, fi ijaarsa weebsaayitii ittisaa beekaa.",
  "academy.stage2.title": "Sadarkaa 2: Ittisa Saayibarii Ogummaa (Sadarkaa 7–10)",
  "academy.stage2.desc": "Hojii ittisa qabatamaa, hordoffii tilimeetirii, qorannoo balaa, fi bulchiinsa sirnaa jabaate.",
  "academy.stage3.title": "Sadarkaa 3: Injinariingii Nageenyaa Sadarkaa Olaanaa (Sadarkaa 11–15)",
  "academy.stage3.desc": "Nageenya sooftiweerii teeknikaa gadi fageenyaa, ittisa API, ijaarsa eenyummaa (Zero Trust), fi saayibarii kireeptoogiraafii.",
  "academy.stage4.title": "Sadarkaa 4: Beekumsa Itti Fufaa & Adda Baafannaa (Sadarkaa 16+)",
  "academy.stage4.desc": "Daandii addaa (Ajajaa Balaa, Ijaaraa Duumessaa, Odeeffannoo Sodaawwanii), fi pirojektii xumuraa.",
  "academy.lvl7.title": "Sadarkaa 7: Tilimeetirii Ittisaa & Hordoffii Galmee",
  "academy.lvl7.desc": "Galmee nageenyaa fudhachuu, hanqina beekamtii adda baasuu, fi tilimeetirii ittisaa.",
  "academy.lvl8.title": "Sadarkaa 8: Qorannoo Balaa Nageenyaa & Sadarkeessuu",
  "academy.lvl8.desc": "Mala balaa adda baasuu, qabannaa meemurii/diiskii, fi qorannoo ragaa foorensikii.",
  "academy.lvl9.title": "Sadarkaa 9: Bulchiinsa Sirna Jabaatee & Baashtiyoonii",
  "academy.lvl9.desc": "Sirna jabeessuu (Linux CIS, Windows GPO), SSH baashtiyoonii, fi mirga xiqqaa RBAC.",
  "academy.lvl10.title": "Sadarkaa 10: Ittisa Daangaa Neetwoorkii & Faayaworlii",
  "academy.lvl10.desc": "Qorannoo paakeetii, calaltuu seensaa/ba'aa, qoqqoodiinsa DMZ, fi IDS/IPS.",
  "academy.lvl11.title": "Sadarkaa 11: Injinariingii Sooftiweerii Nageenyaa & Moodeela Sodaawwanii",
  "academy.lvl11.desc": "Moodeela sodaawwanii STRIDE, SDLC nageenyaa, qophii himaa eeggannoo qabu.",
  "academy.lvl12.title": "Sadarkaa 12: Nageenya Weebii & Ittisa API",
  "academy.lvl12.desc": "OWASP Top 10, ittisa CSRF, dogoggora CORS, fi daangaa saffisa API REST.",
  "academy.lvl13.title": "Sadarkaa 13: Ijaarsa Eenyummaa & Zero Trust",
  "academy.lvl13.desc": "Ijaarsa Zero Trust, OAuth 2.0 PKCE, OpenID Connect, fi mirkaneessa itti fufaa.",
  "academy.lvl14.title": "Sadarkaa 14: Injinariingii Kireeptoogiraafii & Bulchiinsa Furtuu",
  "academy.lvl14.desc": "Algoorizimoota kireeptoogiraafii, nageenya gara fuulduraa, fi naanna'a furtuu KMS.",
  "academy.lvl15.title": "Sadarkaa 15: Ijaarsa Nageenya Dhaabbataa & Qorannoo Balaa",
  "academy.lvl15.desc": "Giddu-galeessota qorannoo balaa (NIST CSF, ISO 27001), fi karoora ciminnaa.",
  "academy.lvl16.title": "Sadarkaa 16+: Beekumsa Itti Fufaa & Daandiiwwan Addaa",
  "academy.lvl16.desc": "Daandiiwwan ittisaa addaa, qorannoo qabatamaa, odeeffannoo sodaawwanii, fi madaallii pirojektii.",
  "academy.sim.title": "Laabii Fakkeessaa Nageenya Saayibarii",
  "academy.sim.desc": "Qormaata shaakalaa qabatamaa bu'uura haala Itoophiyaa irratti xiyyeeffate. Dandeettii keessan nagaadhaan qoraa.",
